#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
struct NFA{vector<vector<pair<int,char>>>g;string s;int p=0;int node(){g.push_back({});return g.size()-1;}void edge(int a,int b,char c=0){g[a].push_back({b,c});}pair<int,int> empty(){int a=node(),b=node();edge(a,b);return {a,b};}pair<int,int> expression(){auto a=sequence();while(p<(int)s.size()&&s[p]=='|'){p++;auto b=sequence();int u=node(),v=node();edge(u,a.first);edge(u,b.first);edge(a.second,v);edge(b.second,v);a={u,v};}return a;}pair<int,int> sequence(){auto a=empty();while(p<(int)s.size()&&s[p]!=')'&&s[p]!='|'){auto b=atom();edge(a.second,b.first);a.second=b.second;}return a;}pair<int,int> atom(){pair<int,int>a;if(s[p]=='('){p++;a=expression();p++;}else{int u=node(),v=node();edge(u,v,s[p++]);a={u,v};}while(p<(int)s.size()&&(s[p]=='*'||s[p]=='+')){char c=s[p++];int u=node(),v=node();edge(u,a.first);edge(a.second,v);edge(a.second,a.first);if(c=='*')edge(u,v);a={u,v};}return a;}void closure(vector<int>&a){queue<int>q;for(int i=0;i<(int)a.size();i++)if(a[i])q.push(i);while(!q.empty()){int u=q.front();q.pop();for(auto[v,c]:g[u])if(!c&&!a[v]){a[v]=1;q.push(v);}}}bool match(string t){auto[start,end]=expression();vector<int>a(g.size());a[start]=1;closure(a);for(char c:t){vector<int>b(g.size());for(int u=0;u<(int)g.size();u++)if(a[u])for(auto[v,ch]:g[u])if(ch==c)b[v]=1;closure(b);a=b;}return a[end];}};int main(){string s,t;while(cin>>s>>t){NFA n;n.s=s;cout<<(n.match(t)?"Yes":"No")<<'\n';}}
